import json, sys
data = json.loads(sys.stdin.read())
result = json.loads(data['result'])
exps = result['data']['experiments']

# Get reference commands from completed experiments of each type
refs = {}
for k, v in exps.items():
    if v.get('status') != 'DONE' or v.get('conclusion') == 'failed':
        continue
    spec = v.get('spec', {})
    cmd = spec.get('command', '')
    if not cmd:
        continue

    # Categorize
    if 'exec-only' in k and '1000' not in k:
        cat = 'exec-only-500'
    elif 'exec-only' in k and '1000' in k:
        cat = 'exec-only-1000'
    elif 'additive-random' in k or 'random-reward' in k:
        cat = 'random'
    elif 'additive-b01' in k:
        cat = 'isr-b01'
    elif 'additive-b03' in k or ('isr' in k and 'b03' in k):
        cat = 'isr-b03'
    elif 'isr-b005' in k:
        cat = 'isr-b005'
    elif 'sweep' in k:
        cat = 'sweep-' + k.split('-')[1]
    else:
        cat = 'other'

    if cat not in refs:
        refs[cat] = []
    refs[cat].append({'id': k, 'command': cmd, 'seed': spec.get('seed'), 'beta': spec.get('beta'), 'config': spec.get('config')})

for cat in sorted(refs.keys()):
    print(f'\n=== {cat} (sample: {refs[cat][0][\"id\"]}) ===')
    e = refs[cat][0]
    print(f'  seed={e[\"seed\"]}, beta={e[\"beta\"]}, config={e[\"config\"]}')
    print(f'  command: {e[\"command\"]}')
